-- Supabase'da allaqachon qo'llangan (initial_schema_v1). Lokal muhit va tarix uchun repoga ko'chirildi.
create table if not exists foydalanuvchilar (id text primary key, tg_id text unique not null, rol text not null check (rol in ('mijoz','sherik','operator','kuryer')), ism text, faol boolean not null default true, yaratilgan timestamptz not null default now());
create table if not exists mijozlar (id text primary key, tg_id text unique, ism text not null, telefon text, manba text, royxatdan_sana date not null default current_date, holat text, izoh text, til text default 'uz', rozilik_vaqt timestamptz, telefon_sorov text, kim_yaratdi text, faol boolean not null default true);
create table if not exists manzillar (id text primary key, mijoz_id text references mijozlar(id), nom text, lat numeric, lng numeric, matn text, moljal text, hudud text, faol boolean not null default true);
create table if not exists ratsionlar (id text primary key, nom text not null, kaloriya integer, tavsif text, tannarx_ovqat integer, tannarx_qadoq_yetkazish integer, faol boolean not null default true);
create table if not exists narxlar (id text primary key, ratsion_id text references ratsionlar(id), kunlik_narx integer not null, qachondan date not null, faol boolean not null default true, yaratilgan timestamptz not null default now());
create table if not exists paketlar (id text primary key, nom text, kunlar integer not null, chegirma_foiz numeric not null default 0, qachondan date not null, faol boolean not null default true, yaratilgan timestamptz not null default now());
create table if not exists keshbek_qoida (id text primary key, foiz numeric not null, amal_muddati_kun integer not null default 60, min_summa integer not null default 0, max_ulush_foiz numeric not null default 30, qachondan date not null, yaratilgan timestamptz not null default now());
create table if not exists buyurtmalar (id text primary key, mijoz_id text references mijozlar(id), manzil_id text references manzillar(id), ratsion_id text references ratsionlar(id), paket_id text references paketlar(id), kunlar integer not null, boshlanish date, tugash date, kunlik_narx integer, chegirma_foiz numeric, keshbek_foiz numeric, keshbek_muddat_kun integer, keshbek_ishlatildi integer default 0, jami integer, tolanadi integer, kunlik_daromad numeric, tolov_holati text, holat text, kim_yaratdi text, yaratuvchi_id text, yaratilgan timestamptz not null default now(), narx_muddati timestamptz, tolov_usuli text, izoh text, qaytarilgan integer default 0, eslatma_yuborildi boolean default false);
create table if not exists yetkazishlar (id text primary key, buyurtma_id text references buyurtmalar(id), mijoz_id text references mijozlar(id), sana date not null, holat text, sabab text, kuryer_id text, hudud text, ratsion_id text, izoh text, vaqt timestamptz, yoldaman_vaqt timestamptz);
create table if not exists tolovlar (id text primary key, buyurtma_id text references buyurtmalar(id), summa integer not null, usul text, sana date, holat text, tasdiqlagan text, chek_rasm text, izoh text, yaratilgan timestamptz not null default now());
create table if not exists keshbek_harakat (id text primary key, mijoz_id text references mijozlar(id), buyurtma_id text, tur text not null, summa integer not null, sana date not null default current_date, tugash_sana date, manba_id text, izoh text, kim text);
create table if not exists xarajat_turkum (id text primary key, nom text not null, guruh text, kod text, hissa boolean default false, faol boolean not null default true);
create table if not exists xarajatlar (id text primary key, sana date not null, turkum_id text references xarajat_turkum(id), summa integer not null, izoh text, chek_rasm text, kim_kiritdi text, holat text, sherik_id text, oylik_id text, faol boolean not null default true, yaratilgan timestamptz not null default now());
create table if not exists xodimlar (id text primary key, ism text not null, lavozim text, oylik_turi text check (oylik_turi in ('qatiy','kunlik','yetkazish')), summa integer, tg_id text, faol boolean not null default true);
create table if not exists oyliklar (id text primary key, xodim_id text references xodimlar(id), oy text not null, hisoblangan integer default 0, avans integer default 0, tolangan integer default 0, sana date);
create table if not exists audit (id text primary key, vaqt timestamptz not null default now(), kim text, amal text, varaq text, yozuv_id text, eski text, yangi text);
create table if not exists sozlama (kalit text primary key, qiymat text);
